import json, re
d = json.load(open('/workspace/public_assets/dev/samples.json'))

# Analyze answer by category
print('Answer by category:')
cat_answers = {}
for q in d:
    cat = q['category']
    ans = q['answer']
    if cat not in cat_answers:
        cat_answers[cat] = {}
    cat_answers[cat][ans] = cat_answers[cat].get(ans, 0) + 1

for cat, answers in cat_answers.items():
    total = sum(answers.values())
    best = max(answers, key=answers.get)
    print(f'  {cat:25s}: {answers}  best={best} ({answers[best]/total*100:.0f}%)')

# Analyze by question word
print()
print('Answer by first word:')
first_word_answers = {}
for q in d:
    text = q['question'].strip()
    # Get first word
    first = text.split()[0].lower().rstrip('?') if text.split() else 'unknown'
    ans = q['answer']
    if first not in first_word_answers:
        first_word_answers[first] = {}
    first_word_answers[first][ans] = first_word_answers[first].get(ans, 0) + 1

for word, answers in sorted(first_word_answers.items(), key=lambda x: -sum(x[1].values())):
    total = sum(answers.values())
    if total >= 2:
        best = max(answers, key=answers.get)
        print(f'  {word:15s} ({total:2d}): {answers}  best={best} ({answers[best]/total*100:.0f}%)')
